INSERT INTO public.resources (title, description, url, resource_type, area, topics, publication_date, published) VALUES
('Inclusive and powerful local youth councils','This guide presents practical approaches to strengthening inclusive Local Youth Councils and increasing young people’s meaningful participation in local decision-making processes.','https://schuman.pl/wp-content/uploads/sites/8/2024/06/MANUAL_Inclusive_powerful_Youth-Councils_ENG.pdf','document','representativeness','{}','2019-01-01',true),
('Effective, representative, and inclusive child participation at the local level','This UNICEF guide explains how local governments can create participatory mechanisms that genuinely include children, especially through councils and other formal structures. It focuses on making participation representative, inclusive, and meaningful rather than symbolic.','https://www.childfriendlycities.org/media/1491/file/Child%20participation%20at%20local%20level.pdf','publication','representativeness','{}','2022-01-01',true),
('Inclusive Municipal Youth Councils - Intervention Manual for local youth and Local Authorities','"This Manual for local youth and Local Authorities was developed as part of the Project funded by the European Union with the title BE-PART (Breaking silos, promoting youth-led intercommunal dialogue against xenophobia at a local level), whcih had the purpose of promoting active, equal and inclusive youth participation in decision making processes at a local / institutional level." (quote has been edited for conciseness)','https://eetaa.gr/evropaika-erga-eetaa/be-part/egcheiridia-be-part/inclusive-municipal-youth-councils/','document','representativeness','{"inclusion","quality standards"}','2024-01-01',true),
('Manual for Establishing and Managing Youth Councils','The manual provides step‑by‑step guidance to set up youth councils: from preparation and selection of members to internal rules, structures, and decision‑making procedures. It also offers tools, templates and examples (e.g. model rules of procedure, meeting templates) to support youth representatives and municipal institutions in making councils transparent, accountable, and sustainable over time.','https://omik.osce.org/sites/default/files/documents/publications/2026/04/ENG_YouthCouncilManual.pdf','document','governance','{}','2026-01-01',true),
('Qualitative guidelines for mechanisms of youth engagement','This publication aims to serve as a resource that offers insights into the diverse approaches to youth engagement. By outlining different mechanisms, sharing real-world examples, and offering practical guides with main features, relevant tips, and resources for successful implementation, it intends to support entities in selecting and adapting the most suitable mechanism of youth engagement for their context.','https://climbingtheladder-project.eu/intellectual-outputs/','document','governance','{}','2025-01-01',true),
('Models and Mechanisms of Youth Engagement','This publication examines diverse models and mechanisms of youth engagement across Europe, with the goal of raising awareness about the importance of involving young people in decision-making processes at the EU, regional, and local levels, while highlighting the need for meaningful participation.','https://climbingtheladder-project.eu/intellectual-outputs/','publication','governance','{"case study","good practice"}','2024-01-01',true),
('Structured and Meaningful Youth Participation in Policy and Decision-Making Processes - Mapping Local, National, EU, and International Good Practices','This study explores effective practices for youth participation in policy and decision-making processes, providing a comprehensive overview of what youth participation means and its key characteristics. The aim of the study is to provide recommendations for mainstreaming structured and meaningful youth participation within the EESC and other EU institutions, in line with the EU Youth Strategy and the UN Youth Strategy.','https://www.eesc.europa.eu/en/our-work/publications-other-work/publications/structured-and-meaningful-youth-participation-policy-and-decision-making-processes-mapping-local-national-eu-and','publication','governance','{"case study","good practice"}','2024-01-01',true),
('Local Youth Councils – Analysis of Policy and Mechanisms','The publication explores the role and effectiveness of Local Youth Councils (LYCs) in ing youth participation in decision-making processes across Europe. It compares the impact of LYCs in Estonia, Lithuania, Norway, and Portugal, analyzing their structures, challenges, and successes. The study provides recommendations and resources to improve youth engagement at the local level, aiming to foster more inclusive and impactful youth participation in governance.','https://dypall.com/catalogue_of_resourc/local-youth-councils-analysis-of-policy-and-mechanisms/','publication','governance','{"case study","good practice"}','2024-01-01',true),
('Local Youth Councils – Mapping Practices','This publication gathers information regarding various aspects of various LYCs, such as their composition, organization, goals, resources available, and other relevant information. Also, it compiles the inside perspectives regarding importance, effectiveness, youth representation, and impact for 10 LYC from 5 countries.','https://dypall.com/catalogue_of_resourc/local-youth-councils-mapping-practices/','publication','governance','{"good practice","case study"}','2022-01-01',true),
('Developing Youth Councils','"This toolbox has been compiled to help local government officials and politicians who want to start, improve, and maintain their own youth councils. It provides both inspiration and a step-by-step guide for setting up and managing these councils. It also explores the questions and challenges youth councils often face and shares some of the lessons that can help local governments include young people more effectively." (quote has been edited for conciseness)','https://icld.se/en/publications/developping-youth-councils/','document','governance','{"guidelines","good practice"}','2026-01-01',true),
('Enhancing youth participation in urban governance through city youth councils','"In addition to a study of the genesis and history of city youth councils, the report provides a landscape analysis of their wide variety. Showing inspiring examples of impactful youth participation in urban governance, this report provides a global overview of city youth councils and their growing importance in urban governance. The report also makes several recommendations, at different scales, to advance reforms to increase the establishment of city youth councils.','https://unesdoc.unesco.org/ark:/48223/pf0000388010','publication','governance','{"good practice","case study"}','2023-01-01',true),
('Manual for Local Youth Councils','This manual provides practical guidance for young members and municipal staff on establishing and running Local Youth Councils in North Macedonia, including steps, tips, and recommendations for creating effective councils.','https://cdn.osce.org/sites/default/files/f/documents/3/b/491132.pdf','document','empowerment','{}','2021-01-01',true),
('Youth Engagement Through Local Involvement: A Step-by-Step Guide to IDEATHON','The IDEATHON guide is a practical manual for youth workers and local authorities on how to run an ideathon that boosts youth participation at the local level. It is organized into clear phases—preparation, promotion, implementation, and evaluation—and focuses on turning young people’s ideas into community action, active citizenship, and democratic engagement.','https://rauhankasvatus.fi/wp-content/uploads/2024/06/IDEATHON-guide_ANG.pdf','document','empowerment','{}','2024-01-01',true),
('Good Practices and Case Studies of Youth Engagement','The publication takes a deep dive into 18 examples of models and mechanisms that successfully foster youth participation in decision-making processes from around Europe. This publication serves as a resource and inspiration for ing youth participation in decision-making processes touching on the local, regional, national and international levels.','https://climbingtheladder-project.eu/intellectual-outputs/','publication','empowerment','{}','2025-01-01',true),
('Quality charter on participatory and inclusive local youth councils','A practical tool which can be used by the local youth council members, youth workers or municipality officers when setting up or improving the local youth council. It provides criteria and indicators for evaluating the local youth council’s fair, meaningful and impactful, and sustainable youth participation in order to make it more inclusive and participatory.','https://dypall.com/catalogue_of_resourc/quality-charter-on-participatory-and-inclusive-local-youth-councils/','document','governance','{"assessment","quality standards"}','2024-01-01',true),
('Toolkit for upgrading local youth councils','Set of training modules based on non-formal education, with the aim to provide young people, youth workers and municipality officers with the capacity to build better youth councils (more inclusive, more digital, more impactful)','https://dypall.com/catalogue_of_resourc/toolkit-for-upgrading-local-youth-councils/','document','governance','{"guidelines","NFE"}','2023-01-01',true),
('MOOC on youth participation and local youth councils','This is a Massive Open Online Course on the quality of local youth councils. It''s meant for stakeholders connected to the framework of local youth councils (young people who are part of the structures or want to become a part, youth workers, and local decision-makers).','https://hop.saltonetwork.eu/courses/YouthParticipationLocalCouncils','video','empowerment','{"guidelines","procedure"}','2024-01-01',true),
('Toolbox for democracy: Let''s build a youth-friendly municipality','','https://dypall.com/catalogue_of_resourc/toolbox-for-democracy/','document','empowerment','{"guidelines","procedure"}','2023-01-01',true),
('Promoting Youth Voices in Local Decision-Making, Global Youth Council Guide','This guide explains how to establish inclusive local youth councils that enable young people to meaningfully participate in political decision-making, offering practical steps, best practices, and solutions to common challenges to ensure effective and sustainable youth engagement in government.','https://www.ndi.org/sites/default/files/Promoting%20Youth%20Voices%20in%20Local%20Decision-Making%2C%20Global%20Youth%20Council%20Guide.pdf','publication','empowerment','{}','2021-01-01',true),
('Building Effective Youth Councils','This guide explains how to create strong youth councils that can influence policy and public decisions. It highlights the need for a solid organizational foundation, youth and adult capacity-building, clear opportunities for action, and real access to decision makers','https://www.ca-ilg.org/sites/main/files/file-attachments/building_effective_youth_councils.pdf','publication','empowerment','{}','2007-01-01',true),
('ADD Something Meaningful - Manual for representatives of local authorities: How to actively involve young people at the local level','This manual is for local authorities and explains how to better involve young people in decision-making at the local level. It presents practical methods, especially the Ideathon approach, to help authorities work with youth, generate ideas, and turn them into community projects or proposals.','https://cesie.org/media/add-manual-for-representatives-local-authorities-en.pdf','document','results','{}','2024-01-01',true);